using System;using System.Text;using UnityEngine;using DG.Tweening;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckGiantSwing {
public enum SwingPhase{Loading,Pumping,Flight,Landing,Replay,AttemptResult,Complete}
public sealed class SwingMatch:SportsEventSession {
 public SportsEventTruck truck;public Rigidbody seat;public Transform rigVisual,pivot;public Transform[] cables;public SportsEventCamera cameraRig;public SportsMotionReplay replay;public int[] points=new int[8],attempts=new int[8];public SwingPhase Phase{get;private set;}public int Current{get;private set;}public int Round{get;private set;}public int Winner{get;private set;}=-1;public int LockedScore{get;private set;}public int Locks{get;private set;}public float Age{get;private set;}public float Energy{get;private set;}public float Angle{get;private set;}public float FlightAge{get;private set;}public float CorrectionSpent{get;private set;}public Vector3 ReleaseVelocity{get;private set;}public Vector3 LandingPoint{get;private set;}public float Best{get;private set;}
 HingeJoint hinge;FixedJoint mount;Tween loading;int eligible=255,tieRound,first,seed;float swingClock,landAge,afterBudget,releaseAngle,energyTarget,flightStart,aimX,rhythmPhase;bool rangeReady;readonly StringBuilder text=new StringBuilder(1200);
 public override string Title=>"TRUCK GIANT SWING";public override int MinimumPlayers=>1;public override int MaximumPlayers=>8;public override int OptionCount=>1;public override string OptionLabel=>"THREE ATTEMPTS · TIMED WEIGHT SHIFT";public override bool ReplayControls=>Phase==SwingPhase.Replay;
 public override string SourcePolicy=>"One to eight competitors take turns. Controller and keyboard sources may be reused between turns.\nMovement pumps; one mapped ACTION releases. Opposite sticks may share a controller.";
 public override void NormalizeSetup(){base.NormalizeSetup();setup.mode=BowlingMode.HotSeat;setup.sharedHotSeat=true;}
 public override bool ValidateSources(out string reason){if(!setup.Validate(out reason))return false;for(int i=0;i<setup.count;i++)if(setup.players[i].source==BowlingSource.Keyboard){var p=setup.players[i];var a=actionKeys[i];if(a==UnityEngine.InputSystem.Key.None||a==UnityEngine.InputSystem.Key.Escape||a==p.forward||a==p.back||a==p.left||a==p.right){reason="Assign a separate release action for slot "+(i+1);return false;}}reason="";return true;}
 public override string Help=>"RIDE THE PENDULUM\nOne to eight competitors take turns. Three attempts each; total zone points win. Tied leaders receive an extra attempt, repeating only while tied. Solo retains a local personal best.\n\nPUMP: time fore/aft movement with the swing. Weight transfer and bounded torque feed a real hinged seat; pushing against its movement wastes energy. Energy is capped. Build for up to35s, then ACTION releases; waiting to the limit releases wherever you are. The truck inherits the ACTUAL seat velocity at its centre of mass, with no added launch impulse or calculated target.\n\nFLIGHT: left/right nudges the path. Release fore/aft once after launch to arm small range correction. The shared1.6s correction budget adds only bounded horizontal acceleration; no hovering or extra lift. After first contact, no control.\n\nFIRST GROUND CONTACT IS FINAL\nThe truck centre of mass in world X/Z at its first ground contact locks10/25/50/100 or zero. Coloured inlaid targets have closed outer boundaries; a smaller higher-value precision zone takes precedence where boundaries overlap. The100 bullseye is nearer than the50 zone. Rolling afterward cannot change points. A missed flight or genuine simulation timeout scores zero.\n\nRecorded actual-motion replays have three angles, slow/normal/fast, rewind and skip. They have no collision or scoring authority. AI-only matches advance automatically. Pause, reconnect and rematch retain the same ownership and setup. Offline only.";
 public override string Header=>Title+" | "+(Round>3?"TIEBREAK "+tieRound:"ATTEMPT "+Round+" / 3")+" | "+setup.players[Current].name;
 public override string Status=>Phase==SwingPhase.Loading?"LOADING THE CRADLE":Phase==SwingPhase.Pumping?"TIME FORE / AFT · ACTION TO RELEASE | "+Energy.ToString("F0")+" / "+SwingRules.EnergyCap+" J · "+Mathf.CeilToInt(SwingRules.Preparation-Age)+"s":Phase==SwingPhase.Flight?"AFTERTOUCH · RELEASE RANGE INPUT TO ARM | "+afterBudget.ToString("F1")+"s":Phase==SwingPhase.Replay?"RECORDED FLIGHT · "+replay.Speed.ToString("0.##")+"× · CAMERA "+(replay.Angle+1)+" / 3 · "+LockedScore+" POINTS":"ZONE "+LockedScore+" · FIRST CONTACT LOCKED";
 public override string Standings{get{text.Clear();for(int i=0;i<setup.count;i++)text.Append(setup.players[i].name).Append("  ").Append(points[i]).Append(" PTS · ").Append(attempts[i]).Append(" THROWS").Append(i==setup.count-1?"":"\n");return text.ToString();}}public override string Results=>(setup.count==1?"PERSONAL BEST "+Best+" PTS":Winner>=0?setup.players[Winner].name+" WINS":"TIED")+"\n\n"+Standings;
 protected override void BeginGame(){Array.Clear(points,0,8);Array.Clear(attempts,0,8);Winner=-1;Round=1;tieRound=Locks=0;eligible=(1<<setup.count)-1;Current=first=0;seed=UnityEngine.Random.Range(1,100000);Best=PlayerPrefs.GetInt("TruckGiantSwing.Best.v1",0);StartAttempt();}
 void RemoveMount(){if(mount!=null){Destroy(mount);mount=null;}}void RemoveHinge(){if(hinge!=null){Destroy(hinge);hinge=null;}}
 void StartAttempt(){loading?.Kill();replay.End();RemoveMount();RemoveHinge();truck.visuals.gameObject.SetActive(true);rigVisual.gameObject.SetActive(true);truck.slot=Current;truck.Prepare(new Vector3(-10,1.5f,0),Quaternion.identity,false);truck.body.isKinematic=true;truck.body.detectCollisions=false;seat.isKinematic=true;seat.position=new Vector3(0,4,0);seat.rotation=Quaternion.identity;Age=swingClock=FlightAge=CorrectionSpent=landAge=0;LockedScore=0;LandingPoint=Vector3.zero;rangeReady=false;Phase=SwingPhase.Loading;float d=(int)setup.players[Current].difficulty;var random=new System.Random(unchecked(seed^(Current*73856093)^(Round*19349663)));releaseAngle=Mathf.Lerp(30,34,d*.5f)+((float)random.NextDouble()*2-1)*Mathf.Lerp(7,2,d*.5f);energyTarget=Mathf.Lerp(1650,2700,d*.5f)+(float)random.NextDouble()*260;aimX=(Current%3==0?-2.5f:Current%3==1?2.4f:4)+((float)random.NextDouble()*2-1)*Mathf.Lerp(1.5f,.3f,d*.5f);rhythmPhase=(float)random.NextDouble()*Mathf.PI*2;loading=truck.transform.DOMove(new Vector3(0,4.45f,0),1.5f).SetEase(Ease.InOutSine).OnComplete(LoadComplete);Gate();}
 void LoadComplete(){if(Phase!=SwingPhase.Loading)return;truck.body.position=new Vector3(0,4.45f,0);truck.body.rotation=Quaternion.identity;truck.body.isKinematic=false;truck.body.detectCollisions=true;seat.isKinematic=false;seat.linearVelocity=seat.angularVelocity=Vector3.zero;Physics.SyncTransforms();hinge=seat.gameObject.AddComponent<HingeJoint>();hinge.autoConfigureConnectedAnchor=false;hinge.anchor=new Vector3(0,SwingRules.Length,0);hinge.connectedAnchor=pivot.position;hinge.axis=Vector3.right;hinge.useLimits=true;hinge.limits=new JointLimits{min=-78,max=78,bounciness=0,contactDistance=2};mount=truck.gameObject.AddComponent<FixedJoint>();mount.connectedBody=seat;mount.enableCollision=false;mount.breakForce=mount.breakTorque=float.PositiveInfinity;Phase=SwingPhase.Pumping;Age=0;replay.ResetRecord();feedback.Play(0,0,true);}
 void Measure(){Angle=Vector3.SignedAngle(Vector3.down,(seat.position-pivot.position).normalized,Vector3.right);float mass=seat.mass+truck.body.mass;Energy=.5f*mass*seat.linearVelocity.sqrMagnitude+mass*Physics.gravity.magnitude*Mathf.Max(0,seat.position.y-4);}
 Vector2 AI(){if(Phase==SwingPhase.Pumping){float omega=seat.angularVelocity.x;float y=Mathf.Abs(omega)>.025f?-Mathf.Sign(omega):Mathf.Abs(Angle)>2?Mathf.Sign(Angle):1;float d=(int)setup.players[Current].difficulty;float rhythm=Mathf.Sin(Age*Mathf.Lerp(2.2f,.4f,d*.5f)+rhythmPhase)*Mathf.Lerp(.7f,.07f,d*.5f);return new Vector2(0,Mathf.Clamp(y+rhythm,-1,1));}if(Phase==SwingPhase.Flight){float d=(int)setup.players[Current].difficulty;float predicted=truck.body.position.x+truck.body.linearVelocity.x*2;float target=aimX;return new Vector2(Mathf.Clamp((target-predicted)*.65f,-1,1)*Mathf.Lerp(.55f,1,d*.5f),0);}return Vector2.zero;}
 protected override void Simulate(float dt){Age+=dt;if(Phase==SwingPhase.Loading)return;if(Phase==SwingPhase.Replay){if(replay.Step(dt))EndReplay();return;}if(Phase==SwingPhase.AttemptResult){if(Age>2)NextAttempt();return;}bool bot=setup.players[Current].source==BowlingSource.AI;var drive=bot?AI():commands[Current];if(Phase==SwingPhase.Pumping){swingClock+=dt;Measure();truck.body.centerOfMass=new Vector3(drive.x*.12f,.03f,drive.y*.28f);float torque=-drive.y*600;if((Energy<SwingRules.EnergyCap&&Mathf.Abs(seat.angularVelocity.x)<1.2f)||torque*seat.angularVelocity.x<0)seat.AddTorque(Vector3.right*torque,ForceMode.Force);bool release=bot?Energy>=energyTarget&&Angle< -releaseAngle&&Angle> -releaseAngle-5&&seat.angularVelocity.x<-.48f:actions[Current];replay.Record(swingClock,3);if(release||Age>=SwingRules.Preparation)Release(drive);return;}if(Phase==SwingPhase.Flight){FlightAge+=dt;swingClock+=dt;if(Mathf.Abs(drive.y)<.12f)rangeReady=true;if(afterBudget>0){var nudge=new Vector3(drive.x,0,rangeReady?drive.y:0);float used=Mathf.Min(afterBudget,dt*nudge.magnitude);if(used>0){truck.body.AddForce(nudge.normalized*.85f*(used/dt),ForceMode.Acceleration);truck.body.AddTorque(new Vector3(nudge.z,0,-nudge.x)*.06f*(used/dt),ForceMode.Acceleration);afterBudget-=used;CorrectionSpent+=used;}}replay.Record(swingClock,3);if(FlightAge>18||truck.body.position.y< -8||Mathf.Abs(truck.body.position.x)>150||Mathf.Abs(truck.body.position.z)>230)Lock(0,truck.body.worldCenterOfMass);return;}if(Phase==SwingPhase.Landing){swingClock+=dt;replay.Record(swingClock,3);landAge+=dt;if(landAge>2.5f)StartReplay();}}
 public void Release(Vector2 held){if(Phase!=SwingPhase.Pumping)return;ReleaseVelocity=seat.GetPointVelocity(truck.body.worldCenterOfMass);var angular=seat.angularVelocity;RemoveMount();truck.body.centerOfMass=new Vector3(0,.03f,0);truck.body.linearVelocity=ReleaseVelocity;truck.body.angularVelocity=angular;Phase=SwingPhase.Flight;Age=FlightAge=0;flightStart=swingClock;afterBudget=SwingRules.Aftertouch;rangeReady=Mathf.Abs(held.y)<.12f;feedback.Play(2,0,true);Pulse(Current,.35f,.18f);Debug.Log("SWING_RELEASE slot="+Current+" angle="+Angle+" energy="+Energy+" velocity="+ReleaseVelocity);}
 public void GroundContact(Collision collision){if(Phase!=SwingPhase.Flight)return;Lock(SwingRules.Zone(truck.body.worldCenterOfMass),truck.body.worldCenterOfMass);feedback.Play(1,collision.relativeVelocity.magnitude);}
 void Lock(int score,Vector3 point){if(Phase!=SwingPhase.Flight)return;LockedScore=score;LandingPoint=point;points[Current]+=score;attempts[Current]++;Locks++;Phase=SwingPhase.Landing;Age=landAge=0;feedback.Play(score>0?5:4,0,true);Debug.Log("SWING_FIRST_GROUND slot="+Current+" round="+Round+" point="+point+" zone="+score);}
 void StartReplay(){truck.body.isKinematic=true;truck.body.detectCollisions=false;truck.visuals.gameObject.SetActive(false);seat.isKinematic=true;rigVisual.gameObject.SetActive(false);Phase=SwingPhase.Replay;Age=0;replay.Record(swingClock+.05f,3);replay.Begin(Mathf.Max(0,flightStart-1.8f));replay.Speed=.5f;Gate();}
 void EndReplay(){replay.End();Phase=SwingPhase.AttemptResult;Age=0;Gate();}
 void NextAttempt(){for(int i=Current+1;i<setup.count;i++)if((eligible&(1<<i))!=0){Current=i;StartAttempt();return;}if(Round<3){Round++;Current=first;StartAttempt();return;}int leaders=SwingRules.Leaders(points,setup.count,eligible);if(setup.count==1||SwingRules.Count(leaders)==1){Winner=First(leaders);Best=Mathf.Max(Best,points[Winner]);if(setup.count==1){PlayerPrefs.SetInt("TruckGiantSwing.Best.v1",(int)Best);PlayerPrefs.Save();}Phase=SwingPhase.Complete;EndMatch();return;}eligible=leaders;Round++;tieRound++;Current=first=First(leaders);StartAttempt();}
 static int First(int mask){for(int i=0;i<8;i++)if((mask&(1<<i))!=0)return i;return 0;}
 public override void ExtraAction(string key){if(!ReplayControls)return;if(key=="replayangle")replay.Angle=(replay.Angle+1)%3;else if(key=="replayspeed")replay.Speed=replay.Speed<1?1:replay.Speed<2?2:replay.Speed<4?4:.25f;else if(key=="replayrewind")replay.Seek(Mathf.Max(0,replay.Cursor-3));else if(key=="replayskip"&&replay.Age>1)EndReplay();}
 protected override void Present(float dt){if(cameraRig==null||truck==null)return;if(cables!=null)for(int i=0;i<cables.Length;i++){var top=pivot.position+Vector3.right*(i==0?-1.7f:1.7f);var bottom=seat.position+seat.rotation*new Vector3(i==0?-1.7f:1.7f,0,0);var delta=top-bottom;cables[i].position=(top+bottom)*.5f;cables[i].rotation=Quaternion.FromToRotation(Vector3.up,delta.normalized);cables[i].localScale=new Vector3(.075f,delta.magnitude*.5f,.075f);}if(Phase==SwingPhase.Pumping||Phase==SwingPhase.Loading)cameraRig.Pose(new Vector3(0,14,3),new Vector3(32,8,-26),60);else{var focus=Phase==SwingPhase.Replay&&replay.Playing?replay.Position(0):truck.body.position;int a=Phase==SwingPhase.Replay?replay.Angle:0;cameraRig.Pose(Vector3.Lerp(focus,new Vector3(0,2,50),.22f),a==0?new Vector3(20,11,-27):a==1?new Vector3(-27,9,4):new Vector3(0,37,-15),68);}}
 protected override void StopGame(){loading?.Kill();RemoveMount();RemoveHinge();replay?.End();if(truck!=null)truck.Park(truck.body.position);if(seat!=null){if(!seat.isKinematic)seat.linearVelocity=seat.angularVelocity=Vector3.zero;seat.isKinematic=true;}}protected override void StopSounds(){truck?.StopSound();}protected override void OnDestroy(){loading?.Kill();base.OnDestroy();}
}
}
